SELECT d.day AS "数据日期",d.battle_type AS "玩法类型",d.battle_type_name AS "玩法名称",d.map_id AS "关卡名称",d.remain_screw_num AS "剩余螺丝数",d.fail_count AS "失败次数",d.fail_users AS "失败人数",a.fail_count AS "关卡总失败次数",a.fail_users AS "关卡总失败人数",CAST(ROUND(d.fail_count*1.000000000000/NULLIF(a.fail_count,0),4) AS decimal(18,4)) AS "失败次数占比",CAST(ROUND(d.fail_users*1.000000000000/NULLIF(a.fail_users,0),4) AS decimal(18,4)) AS "人数占失败人数" FROM (SELECT day,channel,battle_type,battle_type_name,map_id,remain_screw_num,COUNT(*) fail_count,COUNT(DISTINCT pid) fail_users FROM (SELECT * FROM (SELECT f.*,CASE WHEN s.scope=0 THEN '全部渠道' ELSE reg_channel END channel FROM (SELECT * FROM (SELECT e."$part_date" day,u.pid,u.reg_day,u.channel_id reg_channel,e."$part_event" event_name,coalesce(e.battle_type,'未知模式') battle_type,coalesce(nullif(e.battle_type_name,''),e.battle_type,'未知模式') battle_type_name,e.map_id,e.battle_result,e.battle_time,e.remain_screw_num FROM ta.v_event_54 e JOIN (SELECT "#user_id",pid,reg_day,channel_id FROM (SELECT r.*,cast(reg_day AS varchar) "$part_date" FROM (SELECT "#user_id", coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) pid, date(min(first_login_time) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)))) reg_day, coalesce(first_value(channel_id) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) ORDER BY first_login_time NULLS LAST),'未知') channel_id FROM ta.v_user_54 WHERE domain='release' AND game_name='yishuajiushangtou') r) registered WHERE ${PartDate:date2} AND ${Selector:selector3}) u ON e."#user_id"=u."#user_id" WHERE e.game_name='yishuajiushangtou' AND ${PartDate:date1}) f WHERE ${Selector:selector4}) f CROSS JOIN (VALUES (0)) s(scope)) z WHERE event_name='battle_result' AND battle_result=2 AND ('${Variable5}'='全部' OR map_id=TRY_CAST('${Variable5}' AS double))) f GROUP BY 1,2,3,4,5,6) d JOIN (SELECT day,channel,battle_type,battle_type_name,map_id,COUNT(*) fail_count,COUNT(DISTINCT pid) fail_users,AVG(battle_time) avg_time,AVG(remain_screw_num) avg_remain,MIN(remain_screw_num) min_remain,MAX(remain_screw_num) max_remain,COUNT_IF(remain_screw_num IS NULL) missing_remain FROM (SELECT * FROM (SELECT f.*,CASE WHEN s.scope=0 THEN '全部渠道' ELSE reg_channel END channel FROM (SELECT * FROM (SELECT e."$part_date" day,u.pid,u.reg_day,u.channel_id reg_channel,e."$part_event" event_name,coalesce(e.battle_type,'未知模式') battle_type,coalesce(nullif(e.battle_type_name,''),e.battle_type,'未知模式') battle_type_name,e.map_id,e.battle_result,e.battle_time,e.remain_screw_num FROM ta.v_event_54 e JOIN (SELECT "#user_id",pid,reg_day,channel_id FROM (SELECT r.*,cast(reg_day AS varchar) "$part_date" FROM (SELECT "#user_id", coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) pid, date(min(first_login_time) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)))) reg_day, coalesce(first_value(channel_id) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) ORDER BY first_login_time NULLS LAST),'未知') channel_id FROM ta.v_user_54 WHERE domain='release' AND game_name='yishuajiushangtou') r) registered WHERE ${PartDate:date2} AND ${Selector:selector3}) u ON e."#user_id"=u."#user_id" WHERE e.game_name='yishuajiushangtou' AND ${PartDate:date1}) f WHERE ${Selector:selector4}) f CROSS JOIN (VALUES (0)) s(scope)) z WHERE event_name='battle_result' AND battle_result=2 AND ('${Variable5}'='全部' OR map_id=TRY_CAST('${Variable5}' AS double))) f GROUP BY 1,2,3,4,5) a ON d.day=a.day AND d.channel=a.channel AND d.battle_type=a.battle_type AND d.battle_type_name=a.battle_type_name AND d.map_id IS NOT DISTINCT FROM a.map_id ORDER BY d.day DESC,d.channel,d.battle_type,d.map_id,d.remain_screw_num